S = 'js1-support-tickets'; P = fe.REG[S]['abs']; os.chdir(P); done = ['review#1 test files were reformatted by the sweep and the 03 executable-examples block re-synced from the formatted source']

def rewrite02(t):
    t = fe.replace_section(t, r'Validation versus normalization', """`parseTicket` (`server/src/index.ts:269`) validates the shape (subject, body, priority from `asEnum`, an optional agent id, label ids) and normalizes text before anything touches the database. The interesting normalization is the label set: a `PUT` replaces the whole set. `ticket_labels` is a junction table (one row per ticket-label pair), so "replace" is `DELETE FROM ticket_labels WHERE ticket_id = $1` followed by one `INSERT` per label (`linkLabels`, line 247) inside the same transaction. Sending `labelIds: []` therefore means "no labels", not "leave them alone": there is no partial update of the set. Predict what a client that omits `labelIds` gets (validation rejects it; the field is required by `parseTicket`), then check.""") or t
    t = fe.replace_section(t, r'Identity, representation and derived values', """Three identities meet in one ticket: the ticket id (a UUID minted by PostgreSQL), the agent id in `assignee_id` (a foreign key, nullable: `null` means unassigned and is a real state, not a missing value), and the label ids in the junction table. The API returns labels as objects resolved from those ids, so the client never stores label names. Status history (`ticket_events`) is derived data written by `logEvent` at the moment of change; you cannot reconstruct it from the ticket row, which is why it is written in the same transaction as the change and why a no-op status command writes nothing.""") or t
    t = fe.replace_section(t, r'Small design decisions deserve explanations', """Why `DELETE` + `INSERT` for labels rather than a diff? Because the set is small (a handful of labels), the operation is inside a transaction, and a diff needs the current rows first, which is another round trip and another race to reason about. Why is a repeated `PATCH /status` with the same status a no-op (line 176: `SELECT status ... FOR UPDATE`, compare, return)? Because history must record changes, not clicks. Why is the event logged after the update in the same transaction? So a failed audit insert rolls the status back (the fourth test proves it). Each of these is a decision a reviewer will ask about; be ready to defend them.""") or t
    return t
fe.rw(fe.chapter(S, '02'), rewrite02); done.append('review#2 02 sections rewritten around ticket_labels junction rows, DELETE+INSERT replacement, nullable assignee and audit events')
mapping = fx.rename_lesson_fields('client/src/App.tsx'); done.append(f'review#4 harness ids renamed to semantic ids: {mapping}')
